#requires -Version 5.1
[CmdletBinding()]
param(
    [string]$RepoRoot='',
    [string]$ArchiveRoot='',
    [string]$OutputRoot='',
    [ValidateRange(100,5000)][int]$BatchRows=500,
    [ValidateRange(0,256)][int]$WorkerCount=0,
    [ValidateRange(1,1000)][int]$MinFreeGB=15,
    [switch]$ValidateInputsOnly,
    [switch]$SelfTest
)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.IO.Compression
Add-Type -AssemblyName System.IO.Compression.FileSystem

$ExpectedArchives=7163;$ExpectedRows=9183757L;$ExpectedMalformedRows=5L;$ExpectedValidRows=9183752L
$ContextSchemaVersion='CFA_STAGE3_CONTEXT_V1';$SamplingSchemaVersion='CFA_STAGE3_SAMPLE_V2'
$UnbiasedTarget=15000;$NegativeTarget=15000;$EdgeTarget=10000
$Utf8=New-Object System.Text.UTF8Encoding($false)
$BroadAnchors=@('bitcoin','ethereum','crypto','cryptocurrency','cryptocurrencies','blockchain','token','tokens','stablecoin','stablecoins','defi','decentralized finance','web3','nft','nfts','digital asset','digital assets','digital currency','digital currencies','staking','airdrop','airdrops','wallet','wallets','altcoin','altcoins','memecoin','memecoins','crypto market','cryptocurrency market')
$SelectionHeader=@('sample_stratum','selection_rank','lineage_key','context_sha256','context_byte_length','archive_file','archive_timestamp_utc','row_ordinal','record_id','gdelt_date_utc','source_common_name','document_identifier','page_title','themes_raw','persons_raw','organizations_raw','all_names_raw','extras_raw','context_replacement_present','discovery_candidate','discovery_broad_anchor','discovery_candidate_asset_count','discovery_candidate_asset_ids','discovery_candidate_aliases')

function Write-Utf8NoBom{param([string]$Path,[string]$Content);$parent=Split-Path -Parent $Path;if(-not(Test-Path -LiteralPath $parent -PathType Container)){New-Item -ItemType Directory -Path $parent -Force|Out-Null};[System.IO.File]::WriteAllText($Path,$Content,(New-Object System.Text.UTF8Encoding($false)))}
function Csv{param([AllowNull()][object]$Value);$s=if($null-eq$Value){''}else{[string]$Value};if($s.Contains('"')){$s=$s.Replace('"','""')};if($s.Contains(',')-or$s.Contains('"')-or$s.Contains("`r")-or$s.Contains("`n")){return '"'+$s+'"'};return $s}
function Write-CsvRow{param([System.IO.StreamWriter]$Writer,[object[]]$Values);$Writer.WriteLine((@($Values|ForEach-Object{Csv $_})-join','))}
function Open-CsvWriter{param([string]$Path,[string[]]$Header);$w=New-Object System.IO.StreamWriter -ArgumentList $Path,$false,$Utf8;Write-CsvRow $w $Header;return $w}
function Get-FreeGB{param([string]$Path);$full=[System.IO.Path]::GetFullPath($Path);$root=[System.IO.Path]::GetPathRoot($full);$d=New-Object System.IO.DriveInfo $root;return [math]::Round($d.AvailableFreeSpace/1GB,2)}

function Build-ReadingPopulation{
    param([string]$SelectionPath,[string]$ReadingPath,[string]$OutputRoot,[int]$BatchRows)
    $readingHeader=@('context_sha256','context_byte_length','selection_occurrence_count','selection_strata','representative_lineage_key','archive_file','archive_timestamp_utc','row_ordinal','record_id','gdelt_date_utc','source_common_name','document_identifier','page_title','themes_raw','persons_raw','organizations_raw','all_names_raw','extras_raw','context_replacement_present','discovery_candidate','discovery_broad_anchor','discovery_candidate_asset_count','discovery_candidate_asset_ids','discovery_candidate_aliases')
    $states=@{}
    foreach($r in @(Import-Csv -LiteralPath $SelectionPath -Encoding UTF8)){
        $hash=[string]$r.context_sha256
        if(-not$states.ContainsKey($hash)){$states[$hash]=[pscustomobject]@{row=$r;count=0;strata=@{}}}
        $st=$states[$hash];$st.count=[int]$st.count+1;$st.strata[[string]$r.sample_stratum]=$true
    }
    $rw=Open-CsvWriter $ReadingPath $readingHeader
    $manifest=@();$batchWriter=$null;$batchIndex=0;$batchCount=0;$batchStrata=@{};$batchFile=''
    try{
        foreach($hash in @($states.Keys|Sort-Object)){
            $st=$states[$hash];$r=$st.row;$strata=(@($st.strata.Keys|Sort-Object)-join'|')
            $values=@($r.context_sha256,$r.context_byte_length,$st.count,$strata,$r.lineage_key,$r.archive_file,$r.archive_timestamp_utc,$r.row_ordinal,$r.record_id,$r.gdelt_date_utc,$r.source_common_name,$r.document_identifier,$r.page_title,$r.themes_raw,$r.persons_raw,$r.organizations_raw,$r.all_names_raw,$r.extras_raw,$r.context_replacement_present,$r.discovery_candidate,$r.discovery_broad_anchor,$r.discovery_candidate_asset_count,$r.discovery_candidate_asset_ids,$r.discovery_candidate_aliases)
            Write-CsvRow $rw $values
            if($null-eq$batchWriter-or$batchCount-ge$BatchRows){
                if($null-ne$batchWriter){$batchWriter.Dispose();$bp=Join-Path $OutputRoot $batchFile;$manifest += [pscustomobject]@{file=$batchFile;rows=$batchCount;bytes=(Get-Item -LiteralPath $bp).Length;sha256=(Get-FileHash -LiteralPath $bp -Algorithm SHA256).Hash.ToLowerInvariant();stratum_counts=($batchStrata.GetEnumerator()|Sort-Object Name|ForEach-Object{$_.Name+'='+$_.Value})-join'|'}}
                $batchIndex++;$batchFile=('context-discovery-batch-{0:D4}.csv'-f$batchIndex);$batchWriter=Open-CsvWriter (Join-Path $OutputRoot $batchFile) $readingHeader;$batchCount=0;$batchStrata=@{}
            }
            Write-CsvRow $batchWriter $values;$batchCount++
            foreach($ss in $st.strata.Keys){if(-not$batchStrata.ContainsKey($ss)){$batchStrata[$ss]=0};$batchStrata[$ss]=[int]$batchStrata[$ss]+1}
        }
    }finally{
        $rw.Dispose()
        if($null-ne$batchWriter){$batchWriter.Dispose();$bp=Join-Path $OutputRoot $batchFile;$manifest += [pscustomobject]@{file=$batchFile;rows=$batchCount;bytes=(Get-Item -LiteralPath $bp).Length;sha256=(Get-FileHash -LiteralPath $bp -Algorithm SHA256).Hash.ToLowerInvariant();stratum_counts=($batchStrata.GetEnumerator()|Sort-Object Name|ForEach-Object{$_.Name+'='+$_.Value})-join'|'}}
    }
    return [pscustomobject]@{unique_contexts=$states.Count;manifest=$manifest;header=$readingHeader}
}

$CSharp=@'
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Globalization;
using System.IO;
using System.IO.Compression;
using System.Net;
using System.Security.Cryptography;
using System.Text;
