'@
function Install-Engine{if('CfaStage3ContextV3.Engine' -as [type]){return};if($PSVersionTable.PSVersion.Major-ge6){Add-Type -TypeDefinition $CSharp -Language CSharp}else{$refs=@([System.IO.Compression.ZipArchive].Assembly.Location,[System.IO.Compression.ZipFile].Assembly.Location)|Where-Object{-not[string]::IsNullOrWhiteSpace($_)}|Sort-Object -Unique;Add-Type -TypeDefinition $CSharp -Language CSharp -ReferencedAssemblies $refs}}

function New-SyntheticGkgArchive{param([string]$Path,[int]$Seed,[int]$Rows);$dir=Split-Path -Parent $Path;if(-not(Test-Path -LiteralPath $dir)){New-Item -ItemType Directory -Path $dir -Force|Out-Null};$fs=[System.IO.File]::Open($Path,[System.IO.FileMode]::Create,[System.IO.FileAccess]::ReadWrite,[System.IO.FileShare]::None);$zip=[System.IO.Compression.ZipArchive]::new($fs,[System.IO.Compression.ZipArchiveMode]::Create,$false);try{$entry=$zip.CreateEntry(([System.IO.Path]::GetFileNameWithoutExtension($Path)+'.csv'),[System.IO.Compression.CompressionLevel]::Fastest);$writer=New-Object System.IO.StreamWriter -ArgumentList $entry.Open(),$Utf8;try{foreach($i in 1..$Rows){$f=New-Object string[] 27;$f[0]="r-$Seed-$i";$f[1]='20250401000000';$f[3]='example.test';$f[4]="https://example.test/$Seed/$i";if(($i%3)-eq0){$f[8]='ECON_BITCOIN';$f[23]='Avalanche';$f[26]='<PAGE_TITLE>Avalanche (AVAX) and Bitcoin update</PAGE_TITLE>'}elseif(($i%5)-eq0){$f[14]='KeyCorp';$f[23]='KeyCorp';$f[26]='<PAGE_TITLE>KeyCorp (NYSE:KEY) stock update</PAGE_TITLE>'}else{$f[26]='<PAGE_TITLE>Local weather forecast</PAGE_TITLE>'};$writer.WriteLine(($f-join"`t"))}}finally{$writer.Dispose()}}finally{$zip.Dispose();$fs.Dispose()}}

function Invoke-SelfTest{
    Install-Engine;$root=Join-Path ([System.IO.Path]::GetTempPath()) ('cfa-context-v3-'+[guid]::NewGuid().ToString('N'));$src=Join-Path $root 'src';New-Item -ItemType Directory -Path $src -Force|Out-Null
    try{
        $paths=@();foreach($n in 0..11){$name=([datetime]::new(2025,4,1,0,0,0,[DateTimeKind]::Utc).AddMinutes(15*$n).ToString('yyyyMMddHHmmss'))+'.gkg.csv.zip';$p=Join-Path $src $name;New-SyntheticGkgArchive $p ($n+1) 200;$paths+=$p}
        $aliases=@('AVAX','KEY');$bases=@('AVAX','KEY')
        $one=[CfaStage3ContextV3.Engine]::Scan($paths,$aliases,$bases,$BroadAnchors,1,2400)
        $mw=[math]::Min(4,[Environment]::ProcessorCount);if($mw-lt1){$mw=1};$many=[CfaStage3ContextV3.Engine]::Scan($paths,$aliases,$bases,$BroadAnchors,$mw,2400)
        foreach($p in @('ArchivesProcessed','TotalRows','MalformedRows','MissingCriticalRows','ValidRows','DiscoveryCandidates','DiscoveryNegatives')){if([string]$one.$p-ne[string]$many.$p){throw "parallel counter mismatch: $p"}}
        $s1=[CfaStage3ContextV3.Engine]::Select($one.UnbiasedCandidates,$one.NegativeCandidates,$one.EdgeCandidates,5,5,5);$sN=[CfaStage3ContextV3.Engine]::Select($many.UnbiasedCandidates,$many.NegativeCandidates,$many.EdgeCandidates,5,5,5)
        $a=@($s1.Selected|ForEach-Object{$_.Stratum+'|'+$_.Rank+'|'+$_.LineageKey});$b=@($sN.Selected|ForEach-Object{$_.Stratum+'|'+$_.Rank+'|'+$_.LineageKey});if(($a-join"`n")-ne($b-join"`n")){throw 'parallel selection determinism'}
        $o1=Join-Path $root 'one.csv';$oN=Join-Path $root 'many.csv';$t1=Join-Path $root 't1';$tN=Join-Path $root 'tn';New-Item -ItemType Directory -Path $t1,$tN -Force|Out-Null
        $m1=[CfaStage3ContextV3.Engine]::Materialize($paths,$s1.Selected,$o1,$t1,1);$mN=[CfaStage3ContextV3.Engine]::Materialize($paths,$sN.Selected,$oN,$tN,$mw)
        if($m1.RowsWritten-ne$mN.RowsWritten-or(Get-FileHash $o1 -Algorithm SHA256).Hash-ne(Get-FileHash $oN -Algorithm SHA256).Hash){throw 'parallel materialization determinism'}
        Write-Host ('SELF-TEST: PASS | logical_processors='+[Environment]::ProcessorCount+' | workers_tested='+$mw)
    }finally{Remove-Item -LiteralPath $root -Recurse -Force -ErrorAction SilentlyContinue}
}
if($SelfTest){try{Invoke-SelfTest;exit 0}catch{Write-Host 'SELF-TEST: FAIL';Write-Host $_.Exception.Message;if($_.ScriptStackTrace){Write-Host $_.ScriptStackTrace};exit 1}}

try{
    Install-Engine
    if([string]::IsNullOrWhiteSpace($RepoRoot)){$RepoRoot=[System.IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..\..'))};$RepoRoot=(Resolve-Path -LiteralPath $RepoRoot).ProviderPath
    $aliasPath=Join-Path $RepoRoot 'candidate-analysis\CFA-Stage3-News-Aliases.csv';if(-not(Test-Path -LiteralPath $aliasPath -PathType Leaf)){throw "Alias registry missing: $aliasPath"};$aliases=@(Import-Csv -LiteralPath $aliasPath -Encoding UTF8);if($aliases.Count-ne470){throw "Expected 470 alias rows; observed $($aliases.Count)."};$aliasTexts=@($aliases|ForEach-Object{([string]$_.alias_text).Trim()});$baseIds=@($aliases|ForEach-Object{([string]$_.base_asset_id).Trim()})
    $effectiveWorkers=if($WorkerCount-le0){[Environment]::ProcessorCount}else{$WorkerCount}
    if($ValidateInputsOnly){Write-Host ('CFA STAGE 3 CONTEXT V3 INPUTS: PASS | aliases=470 | sampling='+$SamplingSchemaVersion+' | logical_processors='+[Environment]::ProcessorCount+' | workers='+$effectiveWorkers);exit 0}
    $documents=[Environment]::GetFolderPath('MyDocuments');if([string]::IsNullOrWhiteSpace($ArchiveRoot)){$ArchiveRoot=Join-Path $documents 'CFA-local\gdelt-gkg-q2-2025'};if(-not(Test-Path -LiteralPath $ArchiveRoot -PathType Container)){throw "Archive root missing: $ArchiveRoot"};$ArchiveRoot=(Resolve-Path -LiteralPath $ArchiveRoot).ProviderPath
    $files=@(Get-ChildItem -LiteralPath $ArchiveRoot -Recurse -File -Filter '*.gkg.csv.zip'|Where-Object{$_.Name-match'^\d{14}\.gkg\.csv\.zip$'}|Sort-Object Name);if($files.Count-ne$ExpectedArchives){throw "Expected $ExpectedArchives archives; observed $($files.Count)."}
    if([string]::IsNullOrWhiteSpace($OutputRoot)){$parent=Join-Path $documents 'CFA-local\stage3-context-inventory';if(-not(Test-Path -LiteralPath $parent -PathType Container)){New-Item -ItemType Directory -Path $parent -Force|Out-Null};$OutputRoot=Join-Path $parent ((Get-Date).ToUniversalTime().ToString('yyyyMMdd-HHmmss')+'-'+[guid]::NewGuid().ToString('N'))}
    $outputParent=Split-Path -Parent $OutputRoot;if(-not(Test-Path -LiteralPath $outputParent -PathType Container)){New-Item -ItemType Directory -Path $outputParent -Force|Out-Null};$freeBefore=Get-FreeGB $outputParent;if($freeBefore-lt$MinFreeGB){throw "BLOCKED: output drive has $freeBefore GB free; at least $MinFreeGB GB is required before the bounded context run."}
    New-Item -ItemType Directory -Path $OutputRoot -Force|Out-Null;$OutputRoot=(Resolve-Path -LiteralPath $OutputRoot).ProviderPath;$tempRoot=Join-Path $OutputRoot '_temp';New-Item -ItemType Directory -Path $tempRoot -Force|Out-Null
    Write-Host ('Context inventory V3 preflight: output_free_gb='+$freeBefore+' | minimum='+$MinFreeGB+' | workers='+$effectiveWorkers)
    $scan=[CfaStage3ContextV3.Engine]::Scan(@($files.FullName),$aliasTexts,$baseIds,$BroadAnchors,$effectiveWorkers,$ExpectedRows)
    $sel=[CfaStage3ContextV3.Engine]::Select($scan.UnbiasedCandidates,$scan.NegativeCandidates,$scan.EdgeCandidates,$UnbiasedTarget,$NegativeTarget,$EdgeTarget)
    if($sel.UnbiasedCount-ne$UnbiasedTarget-or$sel.NegativeCount-ne$NegativeTarget-or$sel.EdgeCount-ne$EdgeTarget){throw "Discovery selection insufficient: unbiased=$($sel.UnbiasedCount), negative=$($sel.NegativeCount), edge=$($sel.EdgeCount)."}
    $selectionPath=Join-Path $OutputRoot 'context-discovery-selection.csv';$mat=[CfaStage3ContextV3.Engine]::Materialize(@($files.FullName),$sel.Selected,$selectionPath,$tempRoot,$effectiveWorkers);if($mat.RowsWritten-ne40000){throw "Materialized $($mat.RowsWritten) selected rows; expected 40000."}
    $readingPath=Join-Path $OutputRoot 'context-discovery-reading.csv';$reading=Build-ReadingPopulation $selectionPath $readingPath $OutputRoot $BatchRows
    $manifestPath=Join-Path $OutputRoot 'context-discovery-batch-manifest.csv';$mw=New-Object System.IO.StreamWriter -ArgumentList $manifestPath,$false,$Utf8;try{Write-CsvRow $mw @('batch_file','rows','bytes','sha256','stratum_counts');foreach($b in $reading.manifest){Write-CsvRow $mw @($b.file,$b.rows,$b.bytes,$b.sha256,$b.stratum_counts)}}finally{$mw.Dispose()}
    $sourceGate=if($scan.TotalRows-eq$ExpectedRows-and$scan.MalformedRows-eq$ExpectedMalformedRows-and$scan.ValidRows-eq$ExpectedValidRows-and$scan.MissingCriticalRows-eq0){'PASS'}else{'FAIL'};$sampleGate=if($sel.UnbiasedCount-eq15000-and$sel.NegativeCount-eq15000-and$sel.EdgeCount-eq10000-and$mat.RowsWritten-eq40000-and$reading.unique_contexts-gt0){'PASS'}else{'FAIL'};$runGate=if($sourceGate-eq'PASS'-and$sampleGate-eq'PASS'){'PASS'}else{'FAIL'}
    $summary=[ordered]@{run_status=$runGate;gates=[ordered]@{'S3-CTX-001'='PASS';'S3-CTX-002'=$sourceGate;'S3-CTX-003'=$sampleGate;'S3-CTX-004'='BLOCKED';'S3-CTX-005'='BLOCKED';'S3-CTX-006'='BLOCKED';'S3-CTX-007'='BLOCKED';'S3-CTX-008'='BLOCKED'};execution=[ordered]@{implementation='CFA_STAGE3_CONTEXT_V3_BOUNDED_TWO_PASS';logical_processor_count=$scan.LogicalProcessorCount;worker_count=$scan.WorkerCount;pass1_elapsed_seconds=[math]::Round($scan.ElapsedSeconds,3);pass1_rows_per_second=[math]::Round($scan.RowsPerSecond,2);materialization_elapsed_seconds=[math]::Round($mat.ElapsedSeconds,3);output_free_gb_before=$freeBefore;minimum_free_gb=$MinFreeGB};source=[ordered]@{archive_files=$files.Count;archives_processed=$scan.ArchivesProcessed;rows_scanned=$scan.TotalRows;malformed_field_count_rows=$scan.MalformedRows;missing_critical_rows=$scan.MissingCriticalRows;valid_context_rows=$scan.ValidRows};context=[ordered]@{schema_version=$ContextSchemaVersion;global_context_cardinality_status='NOT_APPLICABLE';selected_unique_context_sha256=$reading.unique_contexts;selected_repeated_occurrences=(40000-$reading.unique_contexts);replacement_present_rows=$scan.ReplacementRows;blank_page_title_rows=$scan.BlankTitleRows;blank_themes_rows=$scan.BlankThemesRows;blank_persons_rows=$scan.BlankPersonsRows;blank_organizations_rows=$scan.BlankOrganizationsRows;blank_all_names_rows=$scan.BlankAllNamesRows;blank_source_rows=$scan.BlankSourceRows};discovery=[ordered]@{sampling_schema_version=$SamplingSchemaVersion;provisional_candidate_rows=$scan.DiscoveryCandidates;provisional_negative_rows=$scan.DiscoveryNegatives;unbiased_key_candidates=$scan.UnbiasedCandidates.Count;negative_key_candidates=$scan.NegativeCandidates.Count;edge_key_candidates=$scan.EdgeCandidates.Count;selected_unbiased=$sel.UnbiasedCount;selected_retrieval_negative=$sel.NegativeCount;selected_asset_edge=$sel.EdgeCount;selected_source_rows=40000;selected_unique_reading_contexts=$reading.unique_contexts;batch_rows=$BatchRows;batch_files=$reading.manifest.Count};outputs=[ordered]@{discovery_selection=$selectionPath;discovery_selection_sha256=(Get-FileHash $selectionPath -Algorithm SHA256).Hash.ToLowerInvariant();discovery_reading=$readingPath;discovery_reading_sha256=(Get-FileHash $readingPath -Algorithm SHA256).Hash.ToLowerInvariant();batch_manifest=$manifestPath;batch_manifest_sha256=(Get-FileHash $manifestPath -Algorithm SHA256).Hash.ToLowerInvariant();candidate_alias_registry_sha256=(Get-FileHash $aliasPath -Algorithm SHA256).Hash.ToLowerInvariant()}}
    Write-Utf8NoBom (Join-Path $OutputRoot 'context-inventory-summary.json') (($summary|ConvertTo-Json -Depth 10)+[Environment]::NewLine)
    Remove-Item -LiteralPath $tempRoot -Recurse -Force -ErrorAction SilentlyContinue
    Write-Host 'CFA STAGE 3 CONTEXT INVENTORY V3: COMPLETE';Write-Host ('Evidence directory: '+$OutputRoot);Write-Host ('Rows scanned: '+$scan.TotalRows+' | rows/sec='+[math]::Round($scan.RowsPerSecond,2));Write-Host ('Selected source rows: 40000 | unique contexts='+$reading.unique_contexts);Write-Host ('S3-CTX-002: '+$sourceGate);Write-Host ('S3-CTX-003: '+$sampleGate);if($runGate-ne'PASS'){exit 2};exit 0
}catch{Write-Host 'CFA STAGE 3 CONTEXT INVENTORY V3: FAIL';Write-Host $_.Exception.Message;if($_.ScriptStackTrace){Write-Host $_.ScriptStackTrace};exit 1}
